// Turns the Factory palette snapshot into what code needs at runtime.
//
//   app/styles/factory-themes.css   Factory's palette declarations with a Fabro source comment
//     -> app/lib/factory-palettes.generated.ts          literal colors, for xterm and code
//     -> app/styles/factory-assistant-ui.generated.css  assistant-ui wants HSL channels
//
// To take a new Factory palette: replace the snapshot, update its hash in
// app/lib/appearance.test.ts and app/styles/FACTORY_THEMES.md, then run
// `bun run scripts/factory-themes.ts`. A test fails while the generated files are stale.

import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

export const FACTORY_THEME_IDS = [
  "signal",
  "readability",
  "command",
  "payline",
  "brutalist",
  "graphite",
  "lavender",
] as const;

export type FactoryThemeId = (typeof FACTORY_THEME_IDS)[number];
export type FactoryMode = "light" | "dark";
export type FactoryTokens = Record<string, string>;
export type FactoryPalettes = Record<FactoryThemeId, Record<FactoryMode, FactoryTokens>>;

/** The tokens code reads as literal values. Everything else stays CSS-only. */
const RUNTIME_TOKENS = [
  "bg", "surface", "surface-2", "surface-3",
  "fg", "fg-2", "muted", "line", "line-strong", "input", "ring",
  "primary", "primary-fg", "primary-hover",
  "accent-fill", "accent-ink", "accent-soft", "accent-soft-ink",
  "accent-pop", "accent-pop-fg",
  "rail", "rail-fg", "rail-muted", "rail-strong", "rail-line", "rail-hover", "rail-hover-fg",
  "rail-selected", "rail-selected-fg", "rail-indicator", "rail-ring",
  "ok", "ok-bg", "warn", "warn-bg", "info", "info-bg", "violet", "violet-bg",
  "bad", "bad-bg", "bad-solid", "bad-solid-fg",
  "selection-bg", "selection-fg",
] as const;

/** Each `--aui-*` color and the Factory token it reads. */
const ASSISTANT_UI_ROLES: ReadonlyArray<readonly [string, string]> = [
  ["background", "bg"],
  ["foreground", "fg"],
  ["card", "surface"],
  ["card-foreground", "fg"],
  ["popover", "surface"],
  ["popover-foreground", "fg"],
  ["primary", "primary"],
  ["primary-foreground", "primary-fg"],
  ["secondary", "surface-2"],
  ["secondary-foreground", "fg"],
  ["muted", "surface-2"],
  ["muted-foreground", "muted"],
  ["accent", "accent-soft"],
  ["accent-foreground", "accent-soft-ink"],
  ["destructive", "bad-solid"],
  ["destructive-foreground", "bad-solid-fg"],
  ["border", "line"],
  ["input", "line-strong"],
  ["ring", "ring"],
];

function declarations(body: string): FactoryTokens {
  const tokens: FactoryTokens = {};
  for (const match of body.matchAll(/--([a-z0-9-]+):\s*([^;]+);/g)) {
    tokens[match[1]!] = match[2]!.trim();
  }
  return tokens;
}

/**
 * Resolves the snapshot the way the cascade does. `:root` is Signal navy and every
 * other palette layers on top of it, with `.dark` blocks winning on specificity.
 */
export function parseFactoryPalettes(css: string): FactoryPalettes {
  const blocks = new Map<string, FactoryTokens>();
  for (const match of css.matchAll(/:root(?:\[data-theme="([a-z]+)"\])?(\.dark)?\s*\{([^}]*)\}/g)) {
    blocks.set(`${match[1] ?? "signal"}:${match[2] ? "dark" : "light"}`, declarations(match[3]!));
  }
  const palettes = {} as FactoryPalettes;
  for (const theme of FACTORY_THEME_IDS) {
    const light = theme === "signal" ? {} : blocks.get(`${theme}:light`);
    const dark = theme === "signal" ? {} : blocks.get(`${theme}:dark`);
    if (!light || !dark) throw new Error(`Palette ${theme} is missing from the snapshot`);
    palettes[theme] = {
      light: { ...blocks.get("signal:light"), ...light },
      dark: {
        ...blocks.get("signal:light"),
        ...blocks.get("signal:dark"),
        ...light,
        ...dark,
      },
    };
  }
  return palettes;
}

function camelCase(token: string): string {
  return token.replace(/-([a-z0-9])/g, (_, letter: string) => letter.toUpperCase());
}

export function renderPaletteModule(palettes: FactoryPalettes): string {
  const lines = [
    "// Generated by scripts/factory-themes.ts from app/styles/factory-themes.css. Do not edit.",
    "",
    "export interface FactoryPaletteColors {",
    ...RUNTIME_TOKENS.map((token) => `  ${camelCase(token)}: string;`),
    "}",
    "",
    "export const FACTORY_PALETTES = {",
  ];
  for (const theme of FACTORY_THEME_IDS) {
    lines.push(`  ${theme}: {`);
    for (const mode of ["light", "dark"] as const) {
      lines.push(`    ${mode}: {`);
      for (const token of RUNTIME_TOKENS) {
        const value = palettes[theme][mode][token];
        if (!value) throw new Error(`${theme} ${mode} has no --${token}`);
        lines.push(`      ${camelCase(token)}: "${value}",`);
      }
      lines.push("    },");
    }
    lines.push("  },");
  }
  lines.push("} as const satisfies Record<string, Record<\"light\" | \"dark\", FactoryPaletteColors>>;", "");
  return lines.join("\n");
}

function hslChannels(hex: string): string {
  const value = hex.match(/^#([0-9a-f]{6})$/i)?.[1];
  if (!value) throw new Error(`assistant-ui needs an opaque hex color, got ${hex}`);
  const [r, g, b] = [0, 2, 4].map((start) => parseInt(value.slice(start, start + 2), 16) / 255) as [
    number,
    number,
    number,
  ];
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const lightness = (max + min) / 2;
  const delta = max - min;
  let hue = 0;
  if (delta !== 0) {
    if (max === r) hue = ((g - b) / delta + (g < b ? 6 : 0)) * 60;
    else if (max === g) hue = ((b - r) / delta + 2) * 60;
    else hue = ((r - g) / delta + 4) * 60;
  }
  const saturation = delta === 0 ? 0 : delta / (1 - Math.abs(2 * lightness - 1));
  const round = (number: number) => Math.round(number * 10) / 10;
  return `${round(hue)} ${round(saturation * 100)}% ${round(lightness * 100)}%`;
}

function assistantUiSelector(theme: FactoryThemeId, mode: FactoryMode): string {
  const base = theme === "signal" ? ":root" : `:root[data-theme="${theme}"]`;
  return `${base}${mode === "dark" ? ".dark" : ""} .fabro-chat`;
}

export function renderAssistantUiCss(palettes: FactoryPalettes): string {
  const blocks = [
    "/* Generated by scripts/factory-themes.ts from factory-themes.css. Do not edit.",
    "   assistant-ui wraps these in hsl(var(...)), so they have to be bare channels. */",
    "",
  ];
  for (const theme of FACTORY_THEME_IDS) {
    for (const mode of ["light", "dark"] as const) {
      blocks.push(`${assistantUiSelector(theme, mode)} {`);
      for (const [role, token] of ASSISTANT_UI_ROLES) {
        blocks.push(`  --aui-${role}: ${hslChannels(palettes[theme][mode][token]!)};`);
      }
      blocks.push("}", "");
    }
  }
  return blocks.join("\n");
}

if (import.meta.main) {
  const root = new URL("..", import.meta.url).pathname;
  const palettes = parseFactoryPalettes(
    await readFile(join(root, "app/styles/factory-themes.css"), "utf8"),
  );
  await writeFile(join(root, "app/lib/factory-palettes.generated.ts"), renderPaletteModule(palettes));
  await writeFile(
    join(root, "app/styles/factory-assistant-ui.generated.css"),
    renderAssistantUiCss(palettes),
  );
}
